def transform(grid):
    from collections import Counter, deque
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    base = Counter(v for row in grid for v in row if v != bg).most_common(1)[0][0]
    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny, nx = y+dy, x+dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] != bg and (ny,nx) not in seen:
                        seen.add((ny,nx))
                        q.append((ny,nx))
            components.append(cells)
    size = max(max(max(r for r,c in cells)-min(r for r,c in cells)+1,
                   max(c for r,c in cells)-min(c for r,c in cells)+1)
               for cells in components)
    out = [[base]*size for _ in range(size)]
    for cells in components:
        r0 = min(r for r,c in cells)
        c0 = min(c for r,c in cells)
        for r, c in cells:
            if grid[r][c] != base:
                out[r-r0][c-c0] = grid[r][c]
    return out
